#include <iostream>
#include <cstring>
#include <cctype>

void to_upper_str(char* s) {
    for (size_t i = 0; s[i] != '\0'; ++i) {
        s[i] = static_cast<char>(std::toupper(static_cast<unsigned char>(s[i])));
    }
}

int main() {
    char s[100];
    if (!std::cin.getline(s, 100)) return 0;

    std::cout << "Do dai = " << std::strlen(s) << "\n";

    // So sanh 4 ky tu dau tien voi "HANOI"
    if (std::strncmp(s, "HANOI", 4) == 0) {
        std::cout << "Tien to khop\n";
    } else {
        std::cout << "Tien to khac\n";
    }

    to_upper_str(s);
    std::cout << "In hoa = " << s << "\n";
    return 0;
}

#include <iostream>

int main() {
    const int MAX = 100;
    char s[MAX + 1];
    if (!std::cin.getline(s, MAX + 1)) return 0;

    // 1. Thong ke ky tu 'a'
    int sokitu = 0;
    for (int k = 0; s[k] != '\0'; ++k) {
        if (s[k] == 'a') {
            sokitu++;
        }
    }
    std::cout << "So ki tu a = " << sokitu << "\n";

    // 2. Cat khoang trang 2 dau (In-place Trim theo Vi du 4)
    int i = 0, j = 0;
    while (s[i] == ' ') i++; // Bo qua dau cach dau
    while (s[i] != '\0') {
        s[j++] = s[i++];
    }
    s[j] = '\0'; // Tam thoi ket thuc

    while (j > 0 && s[j - 1] == ' ') {
        j--;
    }
    s[j] = '\0'; // Dat dau ket thuc moi

    std::cout << "Sau khi trim = [" << s << "]\n";
    return 0;
}

#include <iostream>
#include <cstring>

// Mo phong cua so chu chay 10 ky tu qua k buoc lap
void simulate_marquee(const char* text, int window_size, int steps) {
    int len = std::strlen(text);
    char doubled[200];
    std::strcpy(doubled, text);
    std::strcat(doubled, text); // Nhan doi xau theo Vi du 5

    char window[50];
    for (int step = 0; step < steps; ++step) {
        int offset = step % len;
        std::strncpy(window, doubled + offset, window_size);
        window[window_size] = '\0';
        std::cout << "Frame " << step << ": [" << window << "]\n";
    }
}

